using OcctSharp.ConstructionWorkspaces;
using OcctSharp.ExtremaResults;
using OcctSharp.IntersectionResults;
using OcctSharp.Tests.Shared;
using OcctSharp.CopiedCollections;
using OcctSharp.TopologyAssembly;
namespace OcctSharp.Runtime.Tests;
public sealed class FiniteExtremaTests {
 [Fact]public void RealBlConstructionAndFiniteCcCsSsCopiedWorkflow()=>BatchBMFiniteExtremaWorkflow.Run();
 [Fact]public void ParallelCurvesPublishDistanceAndNoInventedPair(){using var a=BatchBMFiniteExtremaWorkflow.Line(new(0,0,0),new(1,0,0));using var b=BatchBMFiniteExtremaWorkflow.Line(new(0,2,0),new(1,0,0));using var result=FiniteExtrema.CurveCurve(a,new(-2,2),b,new(-2,2));Assert.True(result.IsDone);Assert.True(result.IsParallel);Assert.Single(result.Rows);Assert.Equal(4,result.Rows[0].SquareDistance,7);Assert.Null(result.Rows[0].Points);Assert.Equal(4,result.EndpointCombinations.Count);BatchBMFiniteExtremaWorkflow.CheckRows(result);}
 [Fact]public void DisjointParallelSegmentsRetainNativeEndpointSolution(){using var a=BatchBMFiniteExtremaWorkflow.Line(new(0,0,0),new(1,0,0));using var b=BatchBMFiniteExtremaWorkflow.Line(new(0,2,0),new(1,0,0));using var result=FiniteExtrema.CurveCurve(a,new(-3,-2),b,new(2,3));Assert.True(result.IsDone);Assert.False(result.IsParallel);Assert.Single(result.Rows);Assert.Equal(20,result.Rows[0].SquareDistance,7);BatchBMFiniteExtremaWorkflow.CheckRows(result);}
 [Fact]public void CirclesExposeMultipleCoupledStationaryPairs(){using var aResult=ParameterizedConstruction.AnalyticEdge(AnalyticConstructionCurve.Circle,ConstructionFrame.World,0,2*Math.PI,2);using var bResult=ParameterizedConstruction.AnalyticEdge(AnalyticConstructionCurve.Circle,new(new(5,0,0),new(0,0,1),new(1,0,0)),0,2*Math.PI,1);using var ae=aResult.CopyShape();using var be=bResult.CopyShape();using var a=FiniteExtremaGeometry.CopyCurve(ae);using var b=FiniteExtremaGeometry.CopyCurve(be);using var r=FiniteExtrema.CurveCurve(a,new(0,2*Math.PI),b,new(0,2*Math.PI),new(SingleSolution:true));Assert.True(r.IsDone);Assert.True(r.SingleSolutionRequested);Assert.True(r.Rows.Count>1);BatchBMFiniteExtremaWorkflow.CheckRows(r);Assert.Throws<ArgumentException>(()=>FiniteExtrema.CurveCurve(a,new(0,2*Math.PI),b,new(0,2*Math.PI),new(MaximumResults:1)));}
 [Fact]public void PeriodicSeamDomainKeepsNativeParameters(){using var ca=ParameterizedConstruction.AnalyticEdge(AnalyticConstructionCurve.Circle,ConstructionFrame.World,0,2*Math.PI,2);using var edge=ca.CopyShape();using var a=FiniteExtremaGeometry.CopyCurve(edge);using var b=BatchBMFiniteExtremaWorkflow.Line(new(3,0,1),new(1,0,0));using var r=FiniteExtrema.CurveCurve(a,new(5.5,7),b,new(-2,2));Assert.True(r.IsDone);Assert.NotEmpty(r.Rows);BatchBMFiniteExtremaWorkflow.CheckRows(r);}
 [Fact]public void GeneralSplineRetainsPrivateInputAfterSourceDisposal(){using var spline=GeomBSplineCurveCollections.Create(new([new OcctSharp.Values.Coordinates3d(-2,0,0),new(0,1,0),new(2,0,0)]),new([0.0,1]),new([3,3]),2,false);using var edge=TopologyAssembler.Edge(spline,0,1);using var a=FiniteExtremaGeometry.CopyCurve(edge);using var b=BatchBMFiniteExtremaWorkflow.Line(new(0,0,2),new(0,1,0));using var r=FiniteExtrema.CurveCurve(a,new(0,1),b,new(-2,2));Assert.True(r.IsDone);Assert.NotEmpty(r.Rows);a.Dispose();spline.Dispose();edge.Dispose();BatchBMFiniteExtremaWorkflow.CheckRows(r);}
 [Theory][InlineData(0)][InlineData(-1)][InlineData(4097)]public void ResultBudgetsRejectOutsideRange(int budget){using var a=BatchBMFiniteExtremaWorkflow.Line(new(0,0,0),new(1,0,0));Assert.Throws<ArgumentException>(()=>FiniteExtrema.CurveCurve(a,new(-2,2),a,new(-2,2),new(MaximumResults:budget)));}
 [Theory][InlineData(0)][InlineData(-1)][InlineData(1)][InlineData(double.NaN)]public void InvalidTolerancesAreRejected(double tolerance){using var a=BatchBMFiniteExtremaWorkflow.Line(new(0,0,0),new(1,0,0));Assert.Throws<ArgumentException>(()=>FiniteExtrema.CurveCurve(a,new(-2,2),a,new(-2,2),new(FirstTolerance:tolerance)));}
 [Theory][InlineData(2,1)][InlineData(1,1)][InlineData(0,double.PositiveInfinity)][InlineData(0,1000001)]public void InvalidFiniteDomainsAreRejected(double first,double last){using var a=BatchBMFiniteExtremaWorkflow.Line(new(0,0,0),new(1,0,0));Assert.Throws<ArgumentException>(()=>FiniteExtrema.CurveCurve(a,new(first,last),a,new(-2,2)));}
 [Fact]public void DisposalKeepsDetachedRowsAndRejectsGeometryQuery(){using var a=BatchBMFiniteExtremaWorkflow.Line(new(0,0,0),new(1,0,0));using var b=BatchBMFiniteExtremaWorkflow.Line(new(0,0,2),new(0,1,0));using var r=FiniteExtrema.CurveCurve(a,new(-2,2),b,new(-2,2));var rows=r.Rows;r.Dispose();Assert.NotNull(rows[0].Points);Assert.Throws<ObjectDisposedException>(()=>r.EvaluateSource(0,0));a.Dispose();Assert.Throws<ObjectDisposedException>(()=>FiniteExtrema.CurveCurve(a,new(-2,2),b,new(-2,2)));}
 [Fact]public void ConcurrentSamplingAndDisposeUseSafeHandleLease(){using var a=BatchBMFiniteExtremaWorkflow.Line(new(0,0,0),new(1,0,0));using var b=BatchBMFiniteExtremaWorkflow.Line(new(0,0,2),new(0,1,0));var r=FiniteExtrema.CurveCurve(a,new(-2,2),b,new(-2,2));Parallel.For(0,64,i=>{try{Assert.Equal(0,r.EvaluateSource(0,0).X,7);}catch(ObjectDisposedException){}if(i==5)r.Dispose();});r.Dispose();}
 [Fact]public void CopyCurveRejectsFacesAndMissingShape(){using var box=ShapeFactory.CreateBox(1,1,1);Assert.Throws<ArgumentException>(()=>FiniteExtremaGeometry.CopyCurve(box));Assert.Throws<ArgumentNullException>(()=>FiniteExtremaGeometry.CopyCurve(null!));}
 [Fact]public void NormalCurvePlaneReturnsCoupledZeroDistance(){using var edgeResult=ParameterizedConstruction.AnalyticEdge(AnalyticConstructionCurve.Line,new(new(0,0,0),new(0,1,0),new(0,0,1)),-3,3);using var edge=edgeResult.CopyShape();using var curve=FiniteExtremaGeometry.CopyCurve(edge);using var face=BatchBHIntersectionWorkflow.Horizontal();using var plane=RayIntersections.CopySurface(face);using var result=FiniteExtrema.CurveSurface(curve,new(-2,2),plane,new(-3,3,-3,3));Assert.True(result.IsDone);Assert.False(result.IsParallel);Assert.Single(result.Rows);Assert.Equal(0,result.Rows[0].SquareDistance,7);BatchBMFiniteExtremaWorkflow.CheckRows(result);Assert.Throws<ArgumentException>(()=>FiniteExtrema.CurveSurface(curve,new(-2,2),plane,new(-3,3,-3,3),new(SingleSolution:true)));}
 [Fact]public void SpherePlaneRetainsCoupledSurfaceParameters(){using var sphere=BatchBHIntersectionWorkflow.Spherical();using var face=BatchBHIntersectionWorkflow.Horizontal(4);using var plane=RayIntersections.CopySurface(face);using var result=FiniteExtrema.SurfaceSurface(sphere,new(0,2*Math.PI,-Math.PI/2,Math.PI/2),plane,new(-5,5,-5,5));Assert.True(result.IsDone);Assert.False(result.IsParallel);Assert.NotEmpty(result.Rows);BatchBMFiniteExtremaWorkflow.CheckRows(result);}
 [Fact]public void ExcessiveInputComplexityIsRejectedBeforeCurveCopy(){var points=Enumerable.Range(0,257).Select(i=>new OcctSharp.Values.Coordinates3d(i,0,0)).ToArray();var knots=Enumerable.Range(0,257).Select(i=>(double)i).ToArray();var multiplicities=Enumerable.Repeat(1,257).ToArray();multiplicities[0]=multiplicities[^1]=2;using var spline=GeomBSplineCurveCollections.Create(new(points),new(knots),new(multiplicities),1,false);using var edge=TopologyAssembler.Edge(spline,0,256);Assert.Throws<ArgumentException>(()=>FiniteExtremaGeometry.CopyCurve(edge));}
 [Fact]public void CompletedEmptyStationarySetIsDistinctFromEndpointCombinations(){using var a=BatchBMFiniteExtremaWorkflow.Line(new(0,0,0),new(1,0,0));using var b=BatchBMFiniteExtremaWorkflow.Line(new(0,0,2),new(0,1,0));using var result=FiniteExtrema.CurveCurve(a,new(-3,-2),b,new(2,3));Assert.True(result.IsDone);Assert.False(result.IsParallel);Assert.Empty(result.Rows);Assert.Equal(4,result.EndpointCombinations.Count);BatchBMFiniteExtremaWorkflow.CheckRows(result);}
}
